Command:
show system dns
config system dns
set primary {{src_ip}}
set secondary {{dst_ip}}
end

config system global
set admin-sport {{src_port}}
set admin-ssh-port {{dst_port}}
end

config firewall vip
edit "{{vip_name}}"
set extip {{src_ip}}
set mappedip "{{dst_ip}}"
set extport {{src_port}}
set mappedport {{dst_port}}
next
end

config firewall ippool
edit "{{pool_name}}"
set startip {{start_ip}}
set endip {{end_ip}}
next
end

diagnose debug flow filter saddr {{src_ip}}
diagnose debug flow filter daddr {{dst_ip}}
diagnose debug flow trace start {{count}}
diagnose debug enable
diagnose debug disable

get system performance status
diagnose sys top {{interval}} {{count}}
diagnose hardware sysinfo memory

execute ping-options source {{src_ip}}
execute ping {{dst_ip}}
execute traceroute {{dst_ip}}

get router info bgp summary
config router bgp
set as {{asn}}
set router-id {{src_ip}}
config neighbor
edit "{{dst_ip}}"
set remote-as {{remote_asn}}
next
end
end
